using System;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Windows.Forms;using PMStudio;
static class IndependentReferenceTests
{
 static int count;const double Kip=4.4482216152605,KipFt=1.3558179483314;
 static StringBuilder csv=new StringBuilder("Example,Point,Quantity,Published,Calculated,Tolerance,Source\r\n");
 static void Yes(bool value,string text){if(!value)throw new Exception(text);count++;Console.WriteLine("PASS INDEPENDENT "+text);}
 static void Ref(string ex,string point,string variable,double actual,double expected,double tolerance,string source){Yes(Math.Abs(actual-expected)<=tolerance,ex+" "+point+" "+variable+" actual="+actual.ToString("G14",CultureInfo.InvariantCulture)+" published="+expected);csv.AppendLine(ex+","+point+","+variable+","+expected.ToString("G17",CultureInfo.InvariantCulture)+","+actual.ToString("G17",CultureInfo.InvariantCulture)+","+tolerance.ToString("G17",CultureInfo.InvariantCulture)+","+source);}
 [STAThread]static int Main(string[] args){try{
  string folder=args[0];Project p=Examples.CircularReference();Engine.Validate(p);double ey=p.Material.Fy/p.Material.Es;
  // Source: StructurePoint Circular Spiral Column (2022), PDF34 Table8.
  var compression=Engine.Evaluate(p,90,double.PositiveInfinity,false);Ref("Circular","P0","phiP_kip",Reduction.Apply(compression,p,0).P/Kip,1426.2,.051,"SP_Circular_PDF34_Table8");Ref("Circular","cap","phiP_kip",.85*.75*compression.P/Kip,1212.3,.051,"SP_Circular_PDF34_Table8");
  double[] strains={0,ey/2,ey,ey+.003},pp={984.5,642.2,389.2,26.6},mm={208.16,281.43,305.80,295.31};
  for(int i=0;i<strains.Length;i++){var q=DirectionalSolver.AtTensileStrain(p,0,strains[i]);var s=Reduction.Apply(q,p,0);Ref("Circular","control"+i,"phiP_kip",s.P/Kip,pp[i],.051,"SP_Circular_PDF34_Table8");Ref("Circular","control"+i,"phiM_kipft",s.Mx/KipFt,mm[i],.011,"SP_Circular_PDF34_Table8");Yes(Math.Abs(q.MinSteelStrain+strains[i])<1e-10,"circular requested extreme-bar strain "+i);}
  var balance=DirectionalSolver.AtTensileStrain(p,0,ey);Ref("Circular","B","c_in",balance.Depth/25.4,10.28,.0051,"SP_Circular_PDF34_Table7");Ref("Circular","B","Pn_kip",balance.P/Kip,519,.51,"SP_Circular_PDF34_Table7");Ref("Circular","B","Mn_kipft",balance.Mx/KipFt,408,.51,"SP_Circular_PDF34_Table7");
  var pure=DirectionalSolver.AtP(p,0,0);Ref("Circular","pure bending","phiM_kipft",Reduction.Apply(pure,p,0).Mx/KipFt,288.10,.011,"SP_Circular_PDF34_Table8");var tension=Engine.Evaluate(p,90,0,false);Ref("Circular","pure tension","phiP_kip",Reduction.Apply(tension,p,0).P/Kip,-548.6,.051,"SP_Circular_PDF34_Table8");
  var cr=Engine.Analyze(p);Yes(cr.ReportDiagrams[0].ReducedPaths.SelectMany(q=>q).All(q=>q.P<=.85*.75*cr.PMax+1e-5),"spiral cap applied to graph");Export(folder,"reference-circular",p,cr);
  using(var sheet=new ReportSheet()){sheet.Bind(p,cr);sheet.SaveDetailImage(Path.Combine(folder,"professional-detail.png"));sheet.SaveDetailMetafile(Path.Combine(folder,"professional-detail.emf"));}
  using(var png=new Bitmap(Path.Combine(folder,"professional-detail.png")))Yes(png.Width==3000&&png.Height==1950&&Math.Abs(png.HorizontalResolution-300)<1,"standalone professional chart 300 dpi dimensions");
  using(var emf=new System.Drawing.Imaging.Metafile(Path.Combine(folder,"professional-detail.emf")))using(var target=new Bitmap(1000,650))using(var g=Graphics.FromImage(target))
  {Yes(emf.GetMetafileHeader().IsEmfPlusDual(),"export is EMF+ dual vector format");int strings=0,polylines=0,rasters=0;g.EnumerateMetafile(emf,new Point(0,0),(type,flags,length,bytes,play)=>{if(type==System.Drawing.Imaging.EmfPlusRecordType.DrawString)strings++;if(type==System.Drawing.Imaging.EmfPlusRecordType.DrawLines)polylines++;if(type==System.Drawing.Imaging.EmfPlusRecordType.DrawImage||type==System.Drawing.Imaging.EmfPlusRecordType.DrawImagePoints)rasters++;return true;});Yes(strings>20&&polylines>20&&rasters==0,"vector EMF retains text and lines without embedding a raster screenshot");Yes(emf.GetMetafileHeader().Bounds.Width<1200&&emf.GetMetafileHeader().Bounds.Height<800,"EMF frame avoids system-DPI oversize whitespace");g.Clear(Color.White);g.DrawImage(emf,0,0,1000,650);int left=1000,right=0,top=650,bottom=0;for(int yy=0;yy<650;yy+=4)for(int xx=0;xx<1000;xx+=4){Color pixel=target.GetPixel(xx,yy);if(pixel.R<180||pixel.G<180||pixel.B<180){left=Math.Min(left,xx);right=Math.Max(right,xx);top=Math.Min(top,yy);bottom=Math.Max(bottom,yy);}}Yes(right-left>900&&bottom-top>580,"replayed vector chart fills its intended page");target.Save(Path.Combine(folder,"professional-emf-preview.png"));}
  p=Examples.BiaxialReference();Engine.Validate(p);var fixedState=Engine.Evaluate(p,133.9,12.5*25.4,true);
  // The hand table rounds its concrete centroid to 0.01 in before multiplying.
  // Bound 0.21 kip-ft: (448.57 kip)*(0.005 in)/12 = 0.187 plus steel-table rounding.
  Ref("Biaxial","c12.5 alpha43.9","P_kip",fixedState.P/Kip,425.37,.0051,"SP_Rectangular_PDF11_Table1");Ref("Biaxial","c12.5 alpha43.9","Mx_kipft",fixedState.Mx/KipFt,321.28,.21,"SP_Rectangular_PDF11_Table1");Ref("Biaxial","c12.5 alpha43.9","My_kipft",fixedState.My/KipFt,200.64,.21,"SP_Rectangular_PDF11_Table1");
  double ratio=1.6,angle=Math.Atan(1/ratio)*180/Math.PI;var solved=DirectionalSolver.AtP(p,426*Kip,angle);Yes(Math.Abs(solved.P/Kip-426)<1e-8,"biaxial exact target axial equilibrium");Yes(Math.Abs(solved.Mx/solved.My-ratio)<1e-8,"biaxial true moment direction (not neutral-axis angle)");Yes(Math.Abs(solved.Angle-90-angle)>1,"neutral axis is solved independently of moment direction");Export(folder,"reference-biaxial",p,Engine.Analyze(p));
  // Audit the input path that previously interpreted D25 as a 25 mm plain round.
  double[] areas={71.33,126.7,198.6,286.5,387.1,506.7,642.4,794.2,956.6,1140};int index=0;foreach(var size in RebarCatalog.Sizes)Yes(size.Area==areas[index++],"standard rebar nominal area "+size.Name);
  using(var form=new StandardForm()) {typeof(StandardForm).GetMethod("Create",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,null);Yes(form.Project!=null&&form.Project.Bars.Count==12,"standard-section generator bar count");Yes(Math.Abs(form.Project.Bars.Sum(b=>b.Area)-6080.4)<1e-8,"standard-section D25 uses 12 x 506.7 (not pi*25^2/4)");}
  Yes(Math.Abs(Examples.Manual2008().Bars.Sum(b=>b.Area)-48136.5)<1e-7,"handbook retains 95 x D25 nominal area");Yes(Math.Abs(Examples.AciReference(false).Bars[0].Area-645.16)<1e-10,"US example area remains independent of Korean catalog");
  File.WriteAllText(Path.Combine(folder,"independent-reference-comparison.csv"),csv.ToString(),new UTF8Encoding(true));
  File.WriteAllText(Path.Combine(folder,"independent-states.json"),Files.Json(new{Circular=Examples.CircularReference(),Biaxial=p,Manual=Examples.Manual2008(),BiaxialFixed=fixedState,BiaxialSolved=solved,CircularBalanced=balance,ManualBalanced=Engine.Evaluate(Examples.Manual2008(),90,1900*2.0/3,true),ManualMeanDepth=Engine.Evaluate(Examples.Manual2008(),90,(2000-(50*100.0+45*200.0)/95)*2.0/3,true)}),new UTF8Encoding(false));
  Console.WriteLine("PASS INDEPENDENT total: "+count);return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static void Export(string folder,string name,Project p,Analysis r){File.WriteAllText(Path.Combine(folder,name+".pmproj.json"),Files.Json(p));Reports.Csv(Path.Combine(folder,name+"-curves.csv"),p,r);using(var drawing=new ReportDrawing())using(var b=drawing.Create(p,r,2400,2700))b.Save(Path.Combine(folder,name+"-report.png"));using(var plot=new ReportCaseCanvas{Project=p,Result=r})using(var b=new Bitmap(1215,780)){b.SetResolution(144,144);using(var g=Graphics.FromImage(b))plot.Render(g,b.Width,b.Height);b.Save(Path.Combine(folder,name+"-detail.png"));}}
}
